#include <iostream>
#include <vector>
#include <list>
#include <iterator>

int main() {
    std::vector<int> vec = {10, 20, 30, 40, 50};
    std::list<int> lst = {100, 200, 300};

    // std::distance works on any InputIterator;
    // it is O(1) for Random-Access and O(N) for Bidirectional.
    auto vec_dist = std::distance(vec.begin(), vec.end());
    auto lst_dist = std::distance(lst.begin(), lst.end());

    // Random access iterators support pointer-like arithmetic
    auto vec_it = vec.begin() + 3;
    std::cout << "vec distance: " << vec_dist << "\n";
    std::cout << "vec element at index 3: " << *vec_it << "\n";
    std::cout << "lst distance: " << lst_dist << "\n";

    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v = {1, 2, 3, 4, 5, 6};

    // Correct pattern for erasing elements while iterating in C++17
    for (auto it = v.begin(); it != v.end(); /* no increment here */) {
        if (*it % 2 == 0) {
            // erase returns a valid iterator to the next element
            it = v.erase(it);
        } else {
            ++it;
        }
    }

    for (int n : v) {
        std::cout << n << " ";
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <algorithm>
#include <array>
#include <iterator>

char nextLetter() {
    static char letter = 'A';
    return letter++;
}

int main() {
    std::array<char, 10> chars;
    std::ostream_iterator<char> output(std::cout, " ");

    std::fill(chars.begin(), chars.end(), '5');
    std::cout << "chars after filling with 5s:\n";
    std::copy(chars.cbegin(), chars.cend(), output);
    std::cout << "\n\n";

    std::fill_n(chars.begin(), 5, 'A');
    std::cout << "chars after filling five elements with As:\n";
    std::copy(chars.cbegin(), chars.cend(), output);
    std::cout << "\n\n";

    std::generate(chars.begin(), chars.end(), nextLetter);
    std::cout << "chars after generating letters A-J:\n";
    std::copy(chars.cbegin(), chars.cend(), output);
    std::cout << "\n\n";

    std::generate_n(chars.begin(), 5, nextLetter);
    std::cout << "chars after generating K-O for the first five elements:\n";
    std::copy(chars.cbegin(), chars.cend(), output);
    std::cout << "\n";

    return 0;
}
